def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                rays = []
                for ar, ac, sr, sc in ((r, c, -dr, -dc), (r2, c2, dr, dc)):
                    cells = []
                    rr, cc = ar + sr, ac + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        cells.append((rr, cc))
                        rr += sr
                        cc += sc
                    rays.append(cells)
                # The demonstrations show rays continuing only when the other
                # end is stopped by an obstacle or by the border.
                open_rays = [ray for ray in rays if ray]
                if len(open_rays) == 1:
                    for rr, cc in open_rays[0]:
                        out[rr][cc] = color
    return out
